    "2025 年新增贤者 amiibo，适合弓箭与布料目标。": "2025 年新增賢者 amiibo，適合弓箭與布料目標。",
    "6 张三丽鸥联动卡分别对应 Hello Kitty（Etoile）、Cinnamoroll（Marty）、My Melody（Chelsea）、Pompompurin（Chai）、Kuromi（Filly）、Little Twin Stars（Rilla）。可解锁对应村民和主题家具。": "6 張三麗鷗聯動卡分別對應 Hello Kitty（Etoile）、Cinnamoroll（Marty）、My Melody（Chelsea）、Pompompurin（Chai）、Kuromi（Filly）、Little Twin Stars（Rilla）。可解鎖對應村民和主題家具。",
    "BOTW 中扫描后会出现狼林克作为战斗伙伴，生命值取决于在《黄昏公主》中的心数。这是 BOTW 最独特的 amiibo 功能。": "BOTW 中掃描後會出現狼林克作為戰鬥夥伴，生命值取決於在《黃昏公主》中的心數。這是 BOTW 最獨特的 amiibo 功能。",
    "E.M.M.I. amiibo 可补充导弹并增加导弹上限。": "E.M.M.I. amiibo 可補充導彈並增加導彈上限。",
    "FE Engage 的 amiibo 支持非常丰富，Fire Emblem 系列 amiibo 可解锁纹章士戒指、服装票和音乐票。": "FE Engage 的 amiibo 支援非常豐富，火焰之紋章系列 amiibo 可解鎖紋章士戒指、服裝票和音樂票。",
    "K.K. amiibo 可在咖啡馆点播特定 K.K. 歌曲并获得海报。不能搬入岛屿。": "K.K. amiibo 可在咖啡館點播特定 K.K. 歌曲並獲得海報。不能搬入島嶼。",
    "MH Rise 有三款专属 amiibo（猎人、艾露猫、牙猎犬），其他 amiibo 可获得一些基础道具。": "魔物獵人 Rise 有三款專屬 amiibo（獵人、艾露貓、牙獵犬），其他 amiibo 可獲得一些基礎道具。",
    "MK8DX 的 amiibo 支持主要为 Mii 赛车手解锁服装。": "MK8DX 的 amiibo 支援主要為 Mii 賽車手解鎖服裝。",
    "SSBU 是 amiibo 支持最深入的游戏之一，amiibo 角色可作为 FP（Figure Player）参与战斗。": "SSBU 是 amiibo 支援最深入的遊戲之一，amiibo 角色可作為 FP（Figure Player）參與戰鬥。",
    "Skyrim Switch 版中扫描塞尔达系列 amiibo 可解锁海利亚套装、精灵弓和类似 Master Sword 的武器。这是 Skyrim 最独特的 amiibo 功能。": "Skyrim Switch 版中掃描薩爾達系列 amiibo 可解鎖海利亞套裝、精靈弓和類似 Master Sword 的武器。這是 Skyrim 最獨特的 amiibo 功能。",
    "Skyrim Switch 版有独特的 amiibo 支持，可解锁塞尔达联动装备。": "Skyrim Switch 版有獨特的 amiibo 支援，可解鎖薩爾達聯動裝備。",
    "Splatoon 2 amiibo 在 Splatoon 3 中兼容使用，装备外观与 2 代一致。": "斯普拉遁 2 amiibo 在斯普拉遁 3 中相容使用，裝備外觀與 2 代一致。",
    "Splatoon 3 版墨汁女孩 amiibo，扫描后可保存穿搭并获得对应主题装备。": "斯普拉遁 3 版墨汁女孩 amiibo，掃描後可儲存穿搭並獲得對應主題裝備。",
    "Splatoon 3 版墨汁男孩 amiibo，装备为复古 B-Boy 主题。": "斯普拉遁 3 版墨汁男孩 amiibo，裝備為復古 B-Boy 主題。",
    "Splatoon 3 的 amiibo 主要提供装备和穿搭保存功能。部分 amiibo 会在更新后解锁新装备。": "斯普拉遁 3 的 amiibo 主要提供裝備和穿搭儲存功能。部分 amiibo 會在更新後解鎖新裝備。",
    "Splatoon 3 限定彩色墨汁 amiibo。可保存穿搭并获得对应颜色主题装备。": "斯普拉遁 3 限定彩色墨汁 amiibo。可儲存穿搭並獲得對應顏色主題裝備。",
    "Splatoon 3 限定蓝色章鱼 amiibo。可保存穿搭并获得蓝色主题装备。": "斯普拉遁 3 限定藍色章魚 amiibo。可儲存穿搭並獲得藍色主題裝備。",
    "Welcome amiibo 系列含 50 张卡，角色来自《动物森友会 amiibo Festival》等。部分家具系列仅通过此系列获得。": "Welcome amiibo 系列含 50 張卡，角色來自《動物森友會 amiibo Festival》等。部分家具系列僅透過此系列獲得。",
    "XC3 的 amiibo 支持相对有限，主要提供素材和经验值。": "XC3 的 amiibo 支援相對有限，主要提供素材和經驗值。",
    "三款 MH Rise 专属 amiibo 可解锁对应角色的防具外观和猫狗装备外观。每次只能使用一种外观。": "三款魔物獵人 Rise 專屬 amiibo 可解鎖對應角色的防具外觀和貓狗裝備外觀。每次只能使用一種外觀。",
    "修尔克 amiibo 在 XC3 中可解锁 Monado 相关外观。具体奖励需以游戏版本为准。": "修爾克 amiibo 在 XC3 中可解鎖 Monado 相關外觀。具體獎勵需以遊戲版本為準。",
